import asyncio,ast,gzip,hashlib,json,sys
from pathlib import Path
R=Path.cwd();sys.path.insert(0,str(R));O=R/'.local/ri-dogfood-20261023'
from devtools.core.paths import resolve_path
from devtools.resources.commands import Command,CommandExecutor,CommandOutputPolicy
def load(p):return json.loads(p.read_bytes())
def sha(b):return hashlib.sha256(b).hexdigest()
def canon(b):return b if b.startswith(b'\x1f\x8b') else b.replace(b'\r\n',b'\n')
async def git(*args,stdin=None):
 c=Command('git').args(*args).cwd(resolve_path(R))
 if stdin is not None:c=c.with_stdin(stdin)
 r=await CommandExecutor(output_policy=CommandOutputPolicy(max_stdout_bytes=128<<20)).execute(c)
 assert not r.failed and not r.stdout_truncated,args
 return r.stdout
async def main():
 tracked=(await git('ls-files','-z','--','experiments/codex_dogfood/case_0012','experiments/codex_dogfood/case_0013','experiments/codex_dogfood/case_0016')).decode().split('\0');tracked=[p for p in tracked if p]
 records={};checks=[];mismatches=[];anchors=[]
 def remember(path):
  path=path.resolve();assert path.is_relative_to(R);rel=path.relative_to(R).as_posix()
  if rel not in records:
   raw=path.read_bytes();records[rel]=dict(path=rel,sha256=sha(raw),bytes=len(raw))
  return path.read_bytes()
 def check(path,expected,scope,why):
  rel=path.resolve().relative_to(R).as_posix()
  if rel not in records:
   raw=path.read_bytes();records[rel]=dict(path=rel,sha256=sha(raw),canonical_sha256=sha(canon(raw)),bytes=len(raw))
  record=records[rel];actual=record['sha256'] if scope=='physical' else record.get('canonical_sha256')
  if actual is None:actual=sha(canon(path.read_bytes()));record['canonical_sha256']=actual
  entry=dict(path=path.relative_to(R).as_posix(),expected=expected,actual=actual,scope=scope,why=why)
  (checks if expected==actual else mismatches).append(entry)
 # Validate retained capture/report/packet/import seals as inert bytes only.
 manifests=[]
 for p in tracked:
  if Path(p).name in {'integrity.json','failed_audit_hashes.json','reviewed_hashes.json','stage_c_hashes.json','stage_c_r_hashes.json','reconciliation_hashes.json'}:manifests.append(R/p)
 for path in manifests:
  seal=load(path);remember(path)
  for section in ['sha256','files','scientific_outputs']:
   for name,h in seal.get(section,{}).items():
    if not isinstance(h,str) or len(h)!=64:continue
    target=path.parent/name
    if target.is_file():check(target,h,'physical' if ('adjudication' in path.parts or 'stage_d' in path.parts or 'packet' in path.parts or 'blind_packet' in path.parts) else 'canonical-LF',path.relative_to(R).as_posix()+':'+section)
    else:mismatches.append(dict(path=target.relative_to(R).as_posix(),why='Missing retained seal member',manifest=path.relative_to(R).as_posix()))
  for section in ['journal_sha256']:
   for name,h in seal.get(section,{}).items():check(path.parent/name,h,'canonical-LF',str(path.relative_to(R))+':'+section)
  for name,key in [('raw_checkpoint.json','raw_checkpoint_sha256'),('execution_started.json','marker_sha256'),('execution.claim','claim_sha256'),('execution_completed.json','completed_sha256'),('native_context.json','native_context_sha256')]:
   if key in seal:check(path.parent/name,seal[key],'canonical-LF',str(path.relative_to(R))+':'+key)
  for section in ['artifacts','authored']:
   for name,h in seal.get(section,{}).items():check(path.parent/name,h,'canonical-LF',str(path.relative_to(R))+':'+section)
 # Pin checkpoint seal bytes and original implementation closure through raw Git objects.
 specs=[(12,'4ff6d3950e6c0be834f136a649c1a127f91fdba3','integrity.json'),(12,'a2f140d4aa2862c7cc64b80d9608ee6690a6e6bb','stage_b/attempts/case-0012-stage-b-2/integrity.json'),(12,'996ea3b1f9bfc25ed770a390f37fde24077b0710','adjudication/reviewed/reviewed_hashes.json'),(13,'6b18b6e12bbab5a0e131e0afe2fb57b5410b4f16','integrity.json'),(13,'2937e49feb566443f943b91267c59b60b2c7494a','stage_b/attempts/case-0013-stage-b-1/integrity.json'),(13,'f498a790714b9420b79206ad2183ed2f93f44a42','adjudication/reviewed/reviewed_hashes.json'),(16,'e05d9d08297496c4ff5a8e0be1084c4ce1c99a35','integrity.json'),(16,'ceeb6c4da4e2a1db332316239833cf3df6a81831','recovery/integrity.json'),(16,'4925f8896edc49b6162d191a6d348f78dd958a48','stage_b/attempts/case-0016-stage-b-2/integrity.json'),(16,'fb389ac7eec1b009e6403fc0a076a0fe0f6f3af6','adjudication/reviewed/reviewed_hashes.json')]
 queries=[]
 for case,rev,name in specs:
  path=f'experiments/codex_dogfood/case_{case:04}/{name}';raw=await git('show',rev+':'+path);present=remember(R/path);assert raw==present,(rev,path)
  anchors.append(dict(revision=rev,path=path,sha256=sha(raw),same_current_bytes=True))
  value=json.loads(raw)
  for section in (['artifacts','authored','implementation','historical_development'] if name=='integrity.json' else []):
   if '/stage_b/' in path:continue
   for p,h in value.get(section,{}).items():
    if not isinstance(h,str):continue
    full=p if p.startswith(('src/','tests/','scripts/','experiments/','docs/')) or p in ['uv.lock','pyproject.toml'] else path.rsplit('/',1)[0]+'/'+p
    queries.append((rev+':'+full,h))
 # All queries are immutable Git content; no historical code execution or checkout.
 q=list(dict.fromkeys(queries));raw=await git('cat-file','--batch',stdin=('\n'.join(x[0] for x in q)+'\n').encode());offset=0;gitchecks=[]
 for address,h in q:
  end=raw.index(b'\n',offset);header=raw[offset:end].decode();size=int(header.split()[-1]);body=raw[end+1:end+1+size];offset=end+size+2
  assert sha(body)==h,(address,h,sha(body));gitchecks.append(dict(object=address,blob=header.split()[0],sha256=h))
 # Observe lifecycle summaries without reconstructing judgments or metrics.
 summaries={}
 for c in [12,13,16]:
  base=R/f'experiments/codex_dogfood/case_{c:04}';analysis=load(base/'stage_d/analysis.json');remember(base/'stage_d/analysis.json')
  summaries[str(c)]={k:analysis[k] for k in ['outcome','gates','movement_summary','joins','reviewed_summary','gate_evidence','did_we_improve','costs','burdens','graph_novel_overall'] if k in analysis}
 result=dict(artifacts=list(records.values()),successful_hash_checks=checks,current_mismatches=mismatches,git_anchors=anchors,original_git_member_checks=gitchecks,recorded_outcomes=summaries,qualification='Read-only bytes/JSON/Git verification; no historical controller, native pickle, unblinding, adjudication or report construction invoked. Input seals are trust anchors only when independently Git-bound.')
 (O/'evidence.json').write_text(json.dumps(result,indent=2)+'\n',encoding='utf-8')
 print(dict(artifacts=len(records),hash_checks=len(checks),mismatches=len(mismatches),anchors=len(anchors),gitmembers=len(gitchecks)))
 print(json.dumps(mismatches,indent=2)[:5000])
asyncio.run(main())

import asyncio,ast,gzip,hashlib,json,sys
from pathlib import Path
R=Path.cwd();sys.path.insert(0,str(R));O=R/'.local/ri-dogfood-20261023'
from devtools.core.paths import resolve_path
from devtools.resources.commands import Command,CommandExecutor,CommandOutputPolicy
def load(p):return json.loads(p.read_bytes())
def sha(b):return hashlib.sha256(b).hexdigest()
async def git(*args,stdin=None):
 c=Command('git').args(*args).cwd(resolve_path(R))
 if stdin is not None:c=c.with_stdin(stdin)
 r=await CommandExecutor(output_policy=CommandOutputPolicy(max_stdout_bytes=32<<20)).execute(c);assert not r.failed and not r.stdout_truncated;return r.stdout
async def main():
 evidence=load(O/'evidence.json');queries=[]
 for case,rev in [(12,'4ff6d3950e6c0be834f136a649c1a127f91fdba3'),(13,'6b18b6e12bbab5a0e131e0afe2fb57b5410b4f16')]:
  base=f'experiments/codex_dogfood/case_{case:04}/'
  for name,h in load(R/base/'integrity.json')['sha256'].items():queries.append((rev+':'+base+name,h))
  pre=load(R/base/'pre_execution.json')
  for p,h in pre['implementation_sha256'].items():queries.append((rev+':'+p,h))
 q=list(dict.fromkeys(queries));data=await git('cat-file','--batch',stdin=('\n'.join(s for s,h in q)+'\n').encode());offset=0
 for s,h in q:
  end=data.index(b'\n',offset);header=data[offset:end].decode();size=int(header.split()[-1]);raw=data[end+1:end+1+size];offset=end+size+2;assert sha(raw)==h,(s,h,sha(raw));evidence['original_git_member_checks'].append(dict(object=s,blob=header.split()[0],sha256=h))
 # Mechanical current-vs-preserved scientific invocation AST comparison only.
 def functions(p):return {n.name:n for n in ast.parse((R/p).read_text(encoding='utf-8-sig')).body if isinstance(n,(ast.FunctionDef,ast.AsyncFunctionDef))}
 a=functions('experiments/codex_dogfood/case_0016/recovery/original_stage_b/execute.py');b=functions('experiments/codex_dogfood/case_0016/stage_b/execute.py')
 assert all(ast.dump(a[k])==ast.dump(b[k]) for k in ['schedule','universe','observed_ppr'])
 assert [ast.dump(n) for n in next(n for n in a['execute'].body if isinstance(n,ast.Try)).body]==[ast.dump(n) for n in next(n for n in b['execute'].body if isinstance(n,ast.Try)).body]
 evidence['scientific_ast_identity']='Case0016 original/current schedule,universe,observed_ppr and complete scientific execute try-body identical; surrounding authorization/durability changed explicitly'
 # Read saved execution/reviewer summaries, never recompute judgments or ranks.
 evidence['recorded_lifecycle']={}
 for case,attempt in [(12,2),(13,1),(16,2)]:
  base=R/f'experiments/codex_dogfood/case_{case:04}';capture=base/f'stage_b/attempts/case-{case:04}-stage-b-{attempt}';s=load(capture/'summary.json');g=load(base/'adjudication/reviewed/reviewed_statistics.json')
  evidence['recorded_lifecycle'][str(case)]=dict(capture={k:v for k,v in s.items() if k in ['stage_b','execution','operations','journal_events','counts','arms','graph','native_assessments','python_resources_assessed','attempt_1','attempt_2','retries','failures']},reviewed_statistics=g,selected_completions_complete=True)
 evidence['pairwise_binding_checks']={}
 for case in [12,13,16]:
  base=R/f'experiments/codex_dogfood/case_{case:04}'
  if case==12:
   packet=json.loads(gzip.decompress((base/'stage_b/blind_packet/resources.json.gz').read_bytes()));gold=load(base/'adjudication/reviewed/reviewed_gold.json');rs=packet['resources'];cells=gold['cells'];by={r['address']:r for r in rs};assert len(cells)==4779
   for c in cells:assert all(c[k]==by[c['address']][k] for k in ['document_identity','content_identity'])
   p=load(base/'adjudication/primary/stage_c_review.json');i=load(base/'adjudication/independent/stage_c_r_review.json');assert [r['address'] for r in p['resources']]==[r['address'] for r in i['resources']]==[r['address'] for r in rs]
  elif case==13:
   packet=json.loads(gzip.decompress((base/'stage_c/packet/resources.json.gz').read_bytes()));gold=load(base/'adjudication/reviewed/reviewed_gold.json');p=gold['primary'];rs=packet['resources'];assert len(p['resources'])==len(rs)==531
   for n,(r,orig) in enumerate(zip(p['resources'],rs,strict=True)):assert r['identity']==f'R{n:03}' and all(r[k]==orig[k] for k in ['address','content_identity','byte_size','encoding'])
   for c in p['cells']:assert c['address']==p['resources'][int(c['resource'][1:])]['address'] and c['content_identity']==p['resources'][int(c['resource'][1:])]['content_identity']
   cells=p['cells']
  else:
   packet=json.loads(gzip.decompress((base/'stage_c/packet/resources.json.gz').read_bytes()));gold=load(base/'adjudication/reviewed/reviewed_gold.json');p=gold['primary'];rs=packet['resources'];cells=p['cells']
   for n,(r,orig) in enumerate(zip(p['resource_frame'],rs,strict=True)):assert r['resource_index']==n and all(r[k]==orig[k] for k in orig if k!='content')
   for c in cells:assert c['resource_address']==rs[c['resource_index']]['address'] and c['resource_identity']==rs[c['resource_index']]['document_identity']
  evidence['pairwise_binding_checks'][str(case)]=dict(resources=len(rs),cells=len(cells),exact_original_associations_agree=True,qualification='Independent joins over retained original bytes; not semantic adjudication or original treatment execution')
 (O/'evidence.json').write_text(json.dumps(evidence,indent=2)+'\n',encoding='utf-8');print(dict(git_member_checks=len(evidence['original_git_member_checks']),pairwise=evidence['pairwise_binding_checks']))
asyncio.run(main())
